import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to approximate specific ELA features.
    """
    x = np.asarray(x)
    if x.shape != (4,):
        raise ValueError(f"Expected input of shape (4,), got {x.shape}")

    return np.sum((x - [1, -1, 0.5, -0.5])**2) + np.sin(x[0] + x[1]) + np.sin(x[2] + x[3])

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3, x4 = x
    return (x1**2 + 2*x2**2 + x3**2 + 0.5*x4**2) + (0.2 * np.sin(x1 + x2)) + (0.05 * np.exp(0.3 * x1))

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    n = len(x)
    quad_term = np.sum(x**2)
    interaction_term = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            interaction_term += 0.05 * x[i] * x[j]
    skewed_term = np.exp(0.5 * x[0])
    nonlinear_term = np.sin(2 * x[1])
    result = 0.4 * quad_term + 0.1 * interaction_term + 0.15 * skewed_term + 0.15 * nonlinear_term
    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (4,):
        raise ValueError(f"Expected input of shape (4,), got {x.shape}")

    quadratic_term = np.sum(x**2)
    sinusoidal_modulation = np.sin(np.prod(x))
    result = 0.9 * quadratic_term + 0.1 * sinusoidal_modulation
    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (4,):
        raise ValueError(f"Expected input of shape (4,), got {x.shape}")

    quad_term = np.sum(x**2)
    interaction_term = np.sum(x * np.roll(x, 1))
    sin_term = np.sin(quad_term)

    result = 0.6 * quad_term + 0.3 * interaction_term + 0.1 * sin_term

    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (4,):
        raise ValueError(f"Expected input of shape (4,), got {x.shape}")

    quad_term = np.sum(x**2)
    interaction_term = np.prod(x)

    result = quad_term + 0.1 * np.sin(interaction_term)
    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    assert len(x) == 4, "Dimension must be 4"

    f = np.sum(x**2) + 0.1*(x[0]*x[1]) + 0.2*(x[0]**3 - x[1]**3) + 0.05 * np.exp(x[1]) * x[3]**4
    return float(f)
